scwin.divConfirmMsg = null;
scwin.divAlertSubcomMsg = null;
scwin.com_nm1 = null;
scwin.ceo_nm1 = null;
scwin.maj_bz_contn1 = null;
scwin.asst_totamt1 = null;
scwin.debt_totamt1 = null;
scwin.cap_totamt1 = null;
scwin.cap1 = null;
scwin.incld_dd1 = null;
scwin.addRow1 = null;
scwin.com_kor_nm2 = null;
scwin.com_eng_nm2 = null;
scwin.found_dd2 = null;
scwin.incld_dd2 = null;
scwin.ceo_nm2 = null;
scwin.maj_bz_contn2 = null;
scwin.asst_totamt2 = null;
