///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — spotIsuTrdMktTpCd, kclicUsrTpId, ipt_isurCd, DST_URL, ipt_scrollLoc

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "txt_p225", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") !== 6); } }, { id: "if_kclicUsrTpId_8", fn: function(){ return ((dma_pageContext.get("kclicUsrTpId") ?? "") === 'LIST_CORP_DISCLS'); } }, { id: "if_kclicUsrTpId_16", fn: function(){ return ((dma_pageContext.get("kclicUsrTpId") ?? "") === 'LIST_CORP_DISCLS'); } }, { id: "if_spotIsuTrdMktTpCd_19", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") === 1); } }, { id: "if_spotIsuTrdMktTpCd_20", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") !== 1); } }, { id: "if_spotIsuTrdMktTpCd_21", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") === 1); } }, { id: "if_spotIsuTrdMktTpCd_22", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") !== 1); } }, { id: "input_579", fn: function(){ return ((dma_pageContext.get("kclicUsrTpId") ?? "") === 'LIST_CORP_DISCLS'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        scwin.alertSubcom("저장되었습니다.");
        scwin.alertSubcom("수정되었습니다.");
        scwin.alertSubcom("삭제되었습니다.");
        await alertE("오류가 발생하였습니다.\n시스템 담당자에게 문의하시기 바랍니다.");

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods60301.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldods60301: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.divConfirmMsg = $c.util.getComponent('divConfirmMsg');
        scwin.divAlertSubcomMsg = $c.util.getComponent('divAlertSubcomMsg');
        scwin.com_nm1 = $c.util.getComponent('ipt_comNm1');
        scwin.ceo_nm1 = $c.util.getComponent('ipt_ceoNm1');
        scwin.maj_bz_contn1 = $c.util.getComponent('ipt_majBzContn1');
        scwin.asst_totamt1 = $c.util.getComponent('ipt_asstTotamt1');
        scwin.debt_totamt1 = $c.util.getComponent('ipt_debtTotamt1');
        scwin.cap_totamt1 = $c.util.getComponent('ipt_capTotamt1');
        scwin.cap1 = $c.util.getComponent('cap1');
        scwin.incld_dd1 = $c.util.getComponent('ipt_incldDd1');
        scwin.addRow1 = $c.util.getComponent('addRow1');
        scwin.com_kor_nm2 = $c.util.getComponent('ipt_comKorNm2');
        scwin.com_eng_nm2 = $c.util.getComponent('ipt_comEngNm2');
        scwin.found_dd2 = $c.util.getComponent('ipt_foundDd2');
        scwin.incld_dd2 = $c.util.getComponent('ipt_incldDd2');
        scwin.ceo_nm2 = $c.util.getComponent('ipt_ceoNm2');
        scwin.maj_bz_contn2 = $c.util.getComponent('ipt_majBzContn2');
        scwin.asst_totamt2 = $c.util.getComponent('ipt_asstTotamt2');
        scwin.conn_asst_totamt2 = $c.util.getComponent('ipt_connAsstTotamt2');
        scwin.addRow2 = $c.util.getComponent('addRow2');
        scwin.com_kor_nm3 = $c.util.getComponent('ipt_comKorNm3');
        scwin.nat3 = $c.util.getComponent('nat3');
        scwin.ceo_nm3 = $c.util.getComponent('ipt_ceoNm3');
        scwin.maj_bz_contn3 = $c.util.getComponent('ipt_majBzContn3');
        scwin.cap3 = $c.util.getComponent('cap3');
        scwin.isu_shrs3 = $c.util.getComponent('ipt_isuShrs3');
        scwin.acqst_amt3 = $c.util.getComponent('ipt_acqstAmt3');
        scwin.acqst_methd_contn3 = $c.util.getComponent('ipt_acqstMethdContn3');
        scwin.acqst_schdl_dd3 = $c.util.getComponent('ipt_acqstSchdlDd3');
        scwin.addRow3 = $c.util.getComponent('addRow3');
        scwin.init_recvParam();
        scwin.init_conds();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods60301.onpageload' });
    }
};

