/**
 * @method
 * @name othcorpContrbAddRow
 * @description othcorp Contrb Add Row 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.othcorpContrbAddRow = async function () {
    if (scwin.addRow3.style.display === "block") {
        await alertE("입력중인 데이터를 저장한 후에 추가 입력이 가능합니다.");
        return;
    } else {
        $('#removeCheckId3').removeClass("end");
        $('#removeCheckId33').remove();
        $('#removeCheckId33').removeClass("end");
        scwin.addRow3.setStyle("display", "block");
    }
};

