/**
 * @method
 * @name alertSubcom
 * @description alert Subcom 처리
 * @param {String} msg 항목명
 * @returns {void}
 * @hidden N
 */
scwin.alertSubcom = function (msg) {
    layerUI2('#layerUi');
    layerUI2('.layerUi');
    $('#txt_pAlertSubcomText')[0].innerText = msg;
    scwin.divAlertSubcomMsg.setStyle("display", "");
};

/**
 * @method
 * @name closeAlertSubcom
 * @description close Alert Subcom 처리
 * @returns {void}
 * @hidden N
 */
scwin.closeAlertSubcom = function () {
    scwin.divAlertSubcomMsg.setStyle("display", "none");
    scwin.scrollLink((String(((dma_pageContext.get("ipt_scrollLoc") ?? "")) === null ? '' : ((dma_pageContext.get("ipt_scrollLoc") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("ipt_scrollLoc") ?? "")) === null ? '' : ((dma_pageContext.get("ipt_scrollLoc") ?? "")))));
};

/**
 * @method
 * @name closeAlertSubcomE
 * @description close Alert Subcom E 처리
 * @returns {void}
 * @hidden N
 */
scwin.closeAlertSubcomE = function () {
    scwin.divAlertSubcomMsg.setStyle("display", "none");
};

/**
 * @method
 * @name goExcelPopup
 * @description go Excel Popup 처리
 * @param {*} pageGubun pageGubun
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goExcelPopup = async function (pageGubun) {
    const pageURL = '/jldods70207/jldods70207.xml';
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    await $c.win.openPopup((function (__u) { const __s = String(__u === null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(pageURL), { id: "excelUpload", scrollbars: false, resizable: false, width: "750", height: "300", type: "pageFramePopup" }, { method: "excelPop", pageGubun: pageGubun });
};

/**
 * @method
 * @name alertE
 * @description alert E 처리
 * @param {String} msg 항목명
 * @param {*} callback callback
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alertE = async function (msg, callback) {
    // as-is 는 화면 안 #pAlertText/#divAlertMsg 를 만졌다 — 엔진 프레임 접두 때문에
    // 그 선택자는 어디서도 못 찾는다. 표준 알림으로 낸다(메시지가 사라지지 않게).
    await $c.win.alert(msg);
    if (typeof callback === 'function') { await callback(); }
};

async function alertE(msg, callback) { return await scwin.alertE(msg, callback); }
